__global__ void matmul(const float* A, const float* B, float* C,
                       int M, int N, int K)
{
    __shared__ float As[16][16];
    __shared__ float Bs[16][16];

    const int TILE_DIM = 16;
    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;
    float sum = 0.0f;

    for (int tile = 0; tile < K; tile += TILE_DIM) {
        int aCol = tile + threadIdx.x;
        int bRow = tile + threadIdx.y;

        As[threadIdx.y][threadIdx.x] = (row < M && aCol < K) ? A[(long long)row * K + aCol] : 0.0f;
        Bs[threadIdx.y][threadIdx.x] = (bRow < K && col < N) ? B[(long long)bRow * N + col] : 0.0f;

        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[(long long)row * N + col] = sum;
    }
}

